def art_space(x, y, w, h):
    """Night sky, space station, rising rocket."""
    fill_rect(x, y, w, h, NAVY)
    for sx, sy in [(8, 6), (30, 16), (52, 5), (74, 14), (96, 7), (118, 15),
                   (140, 6), (162, 12), (184, 5), (206, 14), (228, 7),
                   (250, 12), (272, 6)]:
        if sx < w - 2:
            fill_rect(x + sx, y + sy, 2, 2, PAPER)
    # station: hub + two solar panels
    fill_rect(x + w // 2 - 46, y + 26, 92, 8, PAPER)
    fill_rect(x + w // 2 - 8, y + 20, 16, 20, GOLD)
    fill_circle(x + w // 2, y + 30, 5, RED)
    # rocket climbing at right
    rx = x + w - 34
    fill_triangle(rx, y + 4, rx - 6, y + 16, rx + 6, y + 16, ORANGE)
    fill_rect(rx - 5, y + 16, 10, 18, PAPER)
    fill_triangle(rx - 5, y + 34, rx - 9, y + 42, rx - 1, y + 34, GOLD)
    fill_triangle(rx + 5, y + 34, rx + 1, y + 34, rx + 9, y + 42, GOLD)


def art_refinery(x, y, w, h):
    """Two refinery towers with flames and smoke."""
    fill_rect(x, y, w, h, SLATE)
    fill_rect(x, y + h - 6, w, 6, INK)
    for tx in (w // 4 - 14, 3 * w // 4 - 14):
        fill_rect(x + tx, y + 22, 28, h - 28, GREY)
        fill_rect(x + tx - 4, y + 16, 36, 6, INK)
        fill_rect(x + tx + 6, y + 4, 16, 12, INK)
        # flame
        fill_triangle(x + tx + 4, y + 16, x + tx + 14, y + 2,
                      x + tx + 24, y + 16, ORANGE)
        fill_triangle(x + tx + 9, y + 16, x + tx + 14, y + 8,
                      x + tx + 19, y + 16, RED)
    fill_circle(x + w // 2, y + 10, 7, PAPER)
    fill_circle(x + w // 2 + 12, y + 6, 5, PAPER)


def art_port(x, y, w, h):
    """Harbour cranes over containers and sea."""
    fill_rect(x, y, w, h, PAPER)
    fill_rect(x, y + h - 12, w, 12, SEA)
    for cx in (w // 4, 3 * w // 4):
        vline(x + cx, y + 6, h - 18, INK, 3)
        draw_line(x + cx, y + 6, x + cx + 34, y + 18, INK)
        draw_line(x + cx, y + 6, x + cx - 22, y + 14, INK)
        vline(x + cx + 30, y + 18, 10, INK, 2)
        fill_rect(x + cx + 26, y + 28, 8, 6, RED)
    fill_rect(x + 8, y + h - 24, 40, 12, RED)
    fill_rect(x + 52, y + h - 24, 40, 12, GREEN)
    fill_rect(x + 96, y + h - 24, 40, 12, BLUE)
    fill_rect(x + 28, y + h - 36, 40, 12, GOLD)


HEAD_ART = (art_space, art_refinery, art_port)


