def draw_masthead():
    w = text_w(FONT_XL, MASTHEAD, "masthead")
    if w > CW:
        issue("OVER-WIDE", "masthead",
              f"date needs {w}px, have {CW}px")
    asc, _ = font_metrics(FONT_XL)
    draw_text_centered(MX + CW // 2, 20 + asc + 6, MASTHEAD, FONT_XL, NAVY,
                       "masthead")
    hline(MX, 94, CW, NAVY, 2)


def draw_wire_times():
    parts = ["WIRE TIMES UTC"]
    for t, what in WIRE_TIMES:
        parts.append(f"{t} {what}")
    line = "   |   ".join(parts)
    w = text_w(FONT_S, line, "wire")
    if w > CW:
        issue("OVER-WIDE", "wire", f"wire line needs {w}px, have {CW}px")
    asc, _ = font_metrics(FONT_S)
    draw_text(MX, 96 + (32 + asc) // 2 + 2, line, FONT_S, INK, "wire")
    hline(MX, 130, CW, GREY, 1)


def draw_numbers():
    col_w = CW // 3
    for i, (num, label) in enumerate(NUMBERS):
        cx = MX + col_w * i + col_w // 2
        w = text_w(FONT_L, num, f"numbers-{i}")
        if w > col_w - 16:
            issue("OVER-WIDE", f"numbers-{i}",
                  f"{num!r} needs {w}px, have {col_w - 16}px")
        asc_l, _ = font_metrics(FONT_L)
        draw_text_centered(cx, 132 + asc_l, num, FONT_L, RED,
                           f"numbers-{i}")
        asc_s, _ = font_metrics(FONT_S)
        draw_text_centered(cx, 132 + asc_l + 18, label, FONT_S, INK,
                           f"numbers-{i}")
        if i:
            vline(MX + col_w * i, 136, 36, GREY, 1)
    hline(MX, 178, CW, NAVY, 2)


def draw_headlines():
    widths = (318, 352, 294)
    xs = (MX, MX + 318 + 10, MX + 318 + 10 + 352 + 10)
    asc, _desc = font_metrics(FONT_H)
    for i, st in enumerate([s for s in STORIES if s["kind"] == "head"]):
        x, wdt = xs[i], widths[i]
        inner_x, inner_w = x + 10, wdt - 20
        box(x, 180, wdt, 210, INK, 1)
        fill_rect(x + 1, 181, wdt - 2, 4, st["color"])
        # illustration
        HEAD_ART[i](inner_x, 190, inner_w, 50)
        # title: two explicit lines
        ty = 246
        for ln in st["title"]:
            lw = text_w(FONT_H, ln, f"head-{st['n']}")
            if lw > inner_w:
                issue("OVER-WIDE", f"head-{st['n']}",
                      f"title line {ln!r} needs {lw}px, have {inner_w}px")
            draw_text(inner_x, ty + asc, ln, FONT_H, INK, f"head-{st['n']}")
            ty += 38
        # deck, max 2 lines
        end_y = draw_para(inner_x, ty + 4, st["deck"], FONT_M, INK,
                          inner_w, 23, max_lines=2, where=f"head-{st['n']}")
        # source line at the card bottom
        asc_s, _ = font_metrics(FONT_S)
        src = f"{st['loc']}  |  {st['source']}"
        sw = text_w(FONT_S, src, f"head-{st['n']}")
        if sw > inner_w:
            issue("OVER-WIDE", f"head-{st['n']}",
                  f"source {src!r} needs {sw}px, have {inner_w}px")
        draw_text(inner_x, 384, src, FONT_S, GREY, f"head-{st['n']}")
        if end_y > 384 - asc_s - 2:
            issue("OVERLAP", f"head-{st['n']}",
                  f"deck ink bottom {end_y}px runs into source line at 384px")


def draw_cards():
    cards = [s for s in STORIES if s["kind"] == "card"]
    col_w, gap = 240, 8
    row_h, row_gap = 114, 6
    for idx, st in enumerate(cards):
        row, col = divmod(idx, 4)
        x = MX + col * (col_w + gap)
        y = 396 + row * (row_h + row_gap)
        inner_x, inner_w = x + 8, col_w - 16
        box(x, y, col_w, row_h, INK, 1)
        fill_rect(x + 1, y + 1, col_w - 2, 3, st["color"])
        # title: two explicit lines, 20px bold
        asc_b, _ = font_metrics(FONT_MB)
        ty = y + 8
        for ln in st["title"]:
            lw = text_w(FONT_MB, ln, f"card-{st['n']}")
            if lw > inner_w:
                issue("OVER-WIDE", f"card-{st['n']}",
                      f"title line {ln!r} needs {lw}px, have {inner_w}px")
            draw_text(inner_x, ty + asc_b, ln, FONT_MB, INK, f"card-{st['n']}")
            ty += 21
        # deck, max 2 lines, 20px regular
        end_y = draw_para(inner_x, ty + 1, st["deck"], FONT_M, INK,
                          inner_w, 20, max_lines=2, where=f"card-{st['n']}")
        # bottom line: color square + location + source
        asc_s, _ = font_metrics(FONT_S)
        src = f"{st['loc']}  |  {st['source']}" if st["loc"] else st["source"]
        sw = text_w(FONT_S, src, f"card-{st['n']}")
        if sw + 16 > inner_w:
            issue("OVER-WIDE", f"card-{st['n']}",
                  f"source {src!r} needs {sw + 16}px, have {inner_w}px")
        sy = y + row_h - 8
        fill_rect(inner_x, sy - 11, 10, 10, st["color"])
        draw_text(inner_x + 16, sy, src, FONT_S, GREY, f"card-{st['n']}")
        if end_y > sy - asc_s - 2:
            issue("OVERLAP", f"card-{st['n']}",
                  f"deck ink bottom {end_y}px runs into source line at {sy}px")


