    hline(MX, 664, CW, RED, 2)
    # two columns of 7 rows each, 30px pitch
    cols = [(MX, items[:7]), (MX + 498, items[7:])]
    for cx, col_items in cols:
        for r, st in enumerate(col_items):
            top = 668 + r * 30
            num = str(st["n"])
            draw_text(cx, top + 19, num, FONT_MB, RED, f"also-{st['n']}")
            nw = text_w(FONT_MB, num, f"also-{st['n']}")
