# ---------------------------------------------------------------------------
# PNG encoder (stdlib only, deterministic)
# ---------------------------------------------------------------------------
def chunk(typ, data):
    out = struct.pack(">I", len(data)) + typ + data
    out += struct.pack(">I", zlib.crc32(typ + data) & 0xFFFFFFFF)
    return out


def encode_png():
    raw = b"".join(b"\x00" + bytes(buf[y * W * 3:(y + 1) * W * 3])
                   for y in range(H))
    ihdr = struct.pack(">IIBBBBB", W, H, 8, 2, 0, 0, 0)
    return (b"\x89PNG\r\n\x1a\n" + chunk(b"IHDR", ihdr)
            + chunk(b"IDAT", zlib.compress(raw, 9))
            + chunk(b"IEND", b""))


def main():
    fill_rect(0, 0, W, H, PAPER)
    draw_masthead()
    draw_wire_times()
    draw_numbers()
    draw_headlines()
    draw_cards()
    draw_also()
    draw_regions()
    draw_datecheck()
    # counts from the data, not hardcoded
    regions = {}
    for s in STORIES:
        regions[s["region"]] = regions.get(s["region"], 0) + 1
    print(f"stories: {len(STORIES)}  regions: {len(regions)}  {regions}")
    out_dir = os.environ.get("MAKEFUN_OUTPUT_DIR", "/output")
    os.makedirs(out_dir, exist_ok=True)
    path = os.path.join(out_dir, "entry.png")
    data = encode_png()
    with open(path, "wb") as f:
        f.write(data)
    print(f"wrote {path}: {len(data)} bytes  sha256 "
          f"{hashlib.sha256(data).hexdigest()}")
    n = report_overflow()
    print(f"RESULT: {'OK' if n == 0 else 'ISSUES FOUND'} ({n})")


if __name__ == "__main__":
    main()
